<script setup lang="ts">
import axios from 'axios';

const botStore = useBotStore();
const saving = ref(false);
const loading = ref(true);
const configData = ref<Record<string, unknown>>({});
const statusMsg = ref('');
const statusType = ref<'ok' | 'err' | ''>('');
const showHowItWorks = ref(false);

// Get authenticated API instance from the active bot
function getApi() {
  // Access the internal api axios instance via the bot's store
  const bot = botStore.activeBot as unknown as Record<string, unknown>;
  // The bot store exposes api indirectly - we'll build our own with the same base
  const loginInfo = useLoginInfo(botStore.selectedBot);
  const baseUrl = loginInfo.baseUrl.value;
  const token = loginInfo.accessToken.value;
  const instance = axios.create({ baseURL: baseUrl, timeout: 20000 });
  instance.interceptors.request.use((req) => {
    if (token) req.headers.set('Authorization', `Bearer ${token}`);
    return req;
  });
  return instance;
}

// Load config from API
async function loadConfig() {
  loading.value = true;
  try {
    const api = getApi();
    const { data } = await api.get('/strategy_config');
    configData.value = data;
  } catch (e: unknown) {
    statusMsg.value = `Failed to load config: ${e}`;
    statusType.value = 'err';
  }
  loading.value = false;
}

// Save config
async function saveConfig() {
  saving.value = true;
  statusMsg.value = '';
  try {
    const api = getApi();
    await api.post('/strategy_config', configData.value);
    statusMsg.value = 'Config saved!';
    statusType.value = 'ok';
  } catch (e: unknown) {
    statusMsg.value = `Save failed: ${e}`;
    statusType.value = 'err';
  }
  saving.value = false;
}

// Save + Stop + Reload + Start
async function saveAndRestart() {
  await saveConfig();
  if (statusType.value === 'err') return;

  try {
    const api = getApi();
    statusMsg.value = 'Stopping bot...';
    await api.post('/stop');
    statusMsg.value = 'Reloading config...';
    await api.post('/reload_config');
    await new Promise((r) => setTimeout(r, 2000));
    statusMsg.value = 'Starting bot...';
    await api.post('/start');
    statusMsg.value = 'Config saved & bot restarted!';
    statusType.value = 'ok';
  } catch (e: unknown) {
    statusMsg.value = `Restart failed: ${e}`;
    statusType.value = 'err';
  }
}

// Section labels and descriptions
const sectionMeta: Record<string, { label: string; color: string; desc: string }> = {
  groups: { label: 'Groups', color: '#64ffda', desc: 'Trading pair groups and BTC reference' },
  risk: { label: 'Risk Management', color: '#f85149', desc: 'Stoploss, ROI, trailing stop' },
  zscore: { label: 'Z-Score Parameters', color: '#58a6ff', desc: 'Z-score calculation windows and entry thresholds' },
  regime: { label: 'Regime Detection', color: '#ffd54f', desc: 'RANGING/CONSOLIDATION/TRENDING detection thresholds' },
  consolidation: { label: 'Consolidation Trades', color: '#ff9800', desc: 'Consolidation-specific entry and exit params' },
  btc_trend: { label: 'BTC Trend Detection', color: '#ffd54f', desc: 'BTC pump/dump/volatility thresholds from 1h candles' },
  volume: { label: 'Volume Filter', color: '#8b949e', desc: 'Volume moving average and minimum threshold' },
  leverage: { label: 'Leverage', color: '#b388ff', desc: 'Funding-adaptive leverage multipliers and limits' },
  dca: { label: 'DCA / Progressive Scaling', color: '#4caf50', desc: 'Add to winners: thresholds and multipliers' },
  exits: { label: 'Exit Logic', color: '#f85149', desc: 'Market stops, dynamic ROI, scalp exit thresholds' },
  funding: { label: 'Funding Data', color: '#8b949e', desc: 'Funding rate rolling window and coins' },
};

function isSection(val: unknown): val is Record<string, unknown> {
  return typeof val === 'object' && val !== null && !Array.isArray(val);
}

function inputType(val: unknown): string {
  if (typeof val === 'number') return 'number';
  if (typeof val === 'boolean') return 'checkbox';
  return 'text';
}

function updateValue(section: string, key: string, event: Event) {
  const target = event.target as HTMLInputElement;
  const sec = configData.value[section] as Record<string, unknown>;
  if (!sec) return;
  const orig = sec[key];
  if (typeof orig === 'number') {
    sec[key] = parseFloat(target.value) || 0;
  } else if (typeof orig === 'boolean') {
    sec[key] = target.checked;
  } else {
    sec[key] = target.value;
  }
}

function updateTopLevel(key: string, event: Event) {
  const target = event.target as HTMLInputElement;
  const orig = configData.value[key];
  if (typeof orig === 'number') {
    configData.value[key] = parseFloat(target.value) || 0;
  } else {
    configData.value[key] = target.value;
  }
}

function updateArrayItem(section: string, key: string, index: number, event: Event) {
  const target = event.target as HTMLInputElement;
  const sec = configData.value[section] as Record<string, unknown>;
  const arr = sec[key] as unknown[];
  if (typeof arr[index] === 'number') {
    arr[index] = parseFloat(target.value) || 0;
  } else {
    arr[index] = target.value;
  }
}

function updateRoiKey(oldKey: string, event: Event) {
  const target = event.target as HTMLInputElement;
  const roi = (configData.value.risk as Record<string, unknown>).minimal_roi as Record<string, number>;
  const val = roi[oldKey];
  delete roi[oldKey];
  roi[target.value] = val;
}

function updateRoiVal(key: string, event: Event) {
  const target = event.target as HTMLInputElement;
  const roi = (configData.value.risk as Record<string, unknown>).minimal_roi as Record<string, number>;
  roi[key] = parseFloat(target.value) || 0;
}

onMounted(() => {
  loadConfig();
});
</script>

<template>
  <div class="flex flex-col gap-3 p-4 h-full overflow-y-auto">
    <!-- Header -->
    <div
      class="flex items-center gap-3 p-3 rounded-md dark:bg-surface-900 dark:border-surface-700 border"
    >
      <span class="text-xl font-bold" style="color: #64ffda">Strategy Config</span>
      <span class="text-base text-muted-color">v50_config.json</span>
      <div class="flex gap-2 ms-auto">
        <button
          class="px-4 py-2 rounded-md text-base font-bold"
          style="background: #238636; color: #fff; border: none; cursor: pointer"
          :disabled="saving"
          @click="saveConfig"
        >
          {{ saving ? 'Saving...' : 'Save' }}
        </button>
        <button
          class="px-4 py-2 rounded-md text-base font-bold"
          style="background: #f85149; color: #fff; border: none; cursor: pointer"
          :disabled="saving"
          @click="saveAndRestart"
        >
          {{ saving ? '...' : 'Save & Restart Bot' }}
        </button>
      </div>
    </div>

    <!-- Status -->
    <div
      v-if="statusMsg"
      class="px-3 py-2 rounded-md text-base font-bold"
      :style="{
        background: statusType === 'ok' ? '#23863622' : '#f8514922',
        color: statusType === 'ok' ? '#4caf50' : '#f85149',
        border: `1px solid ${statusType === 'ok' ? '#238636' : '#f85149'}`,
      }"
    >
      {{ statusMsg }}
    </div>

    <!-- Loading -->
    <div v-if="loading" class="p-4 text-muted-color">Loading config...</div>

    <template v-else>
      <!-- How it works (collapsible) -->
      <div class="rounded-md dark:bg-surface-900 dark:border-surface-700 border">
        <div
          class="flex items-center gap-2 px-3 py-2 cursor-pointer select-none"
          @click="showHowItWorks = !showHowItWorks"
        >
          <span style="color: #64ffda; font-size: 14px">{{ showHowItWorks ? '\u25BC' : '\u25B6' }}</span>
          <span class="font-bold" style="color: #64ffda">How it works — V50 Combined</span>
        </div>
        <div v-show="showHowItWorks" class="px-4 pb-4 text-base leading-loose" style="color: #c9d1d9">
          <p class="mb-2"><b style="color: #ffd54f">Overview:</b> V50 Combined is a mean-reversion pairs trading strategy on Hyperliquid futures (15m). It splits 4 trading pairs into 2 correlated groups and trades the z-score spread between them. BTC is used as a regime reference (not traded). Funding rate adapts leverage.</p>
          <p class="mb-2"><b style="color: #4caf50">Group A</b> (XRP, ADA) — LONG only | <b style="color: #b388ff">Group B</b> (SOL, LINK) — SHORT + LONG</p>
          <p class="mb-2"><b style="color: #ffd54f">4 Trade Types:</b> mr_long_a (ranging), mr_short_b (ranging), mr_long_b (ranging), consol_long_a (consolidation)</p>
          <p class="mb-2"><b style="color: #ffd54f">Regimes:</b> RANGING = mean-reversion on | CONSOLIDATION = consol longs only | TRENDING = all blocked</p>
          <p class="mb-2"><b style="color: #ffd54f">Exits:</b> z-score scalp, dynamic ROI, market stops (chaos/dump/pump/regime), trailing stop, stoploss</p>
          <p><b style="color: #ffd54f">DCA:</b> Progressive adds at +0.3%/+0.6%/+1.0% — only when in profit, never averages down</p>
        </div>
      </div>

      <!-- Top-level params -->
      <div class="rounded-md dark:bg-surface-900 dark:border-surface-700 border p-3">
        <h3 class="text-base font-bold mb-2" style="color: #64ffda">General</h3>
        <div class="grid grid-cols-3 gap-2">
          <template v-for="(val, key) in configData" :key="key">
            <div
              v-if="typeof val === 'string' || typeof val === 'number'"
              class="flex flex-col gap-1"
            >
              <label class="text-base text-muted-color">{{ key }}</label>
              <input
                :type="inputType(val)"
                :value="val"
                :step="typeof val === 'number' ? 'any' : undefined"
                class="px-2 py-1 rounded-sm text-base border dark:border-surface-700 dark:bg-surface-900"
                @change="updateTopLevel(key as string, $event)"
              />
            </div>
          </template>
        </div>
      </div>

      <!-- Section editors -->
      <template v-for="(val, sectionKey) in configData" :key="sectionKey">
        <div
          v-if="isSection(val) && sectionKey !== '_comment' && sectionMeta[sectionKey as string]"
          class="rounded-md border p-3"
          :style="{ borderColor: sectionMeta[sectionKey as string]?.color || '#30363d', background: '#0d1117' }"
        >
          <h3 class="text-base font-bold mb-1" :style="{ color: sectionMeta[sectionKey as string]?.color }">
            {{ sectionMeta[sectionKey as string]?.label || sectionKey }}
          </h3>
          <p class="text-base text-muted-color mb-2">{{ sectionMeta[sectionKey as string]?.desc }}</p>

          <div class="grid grid-cols-3 gap-2">
            <template v-for="(fieldVal, fieldKey) in (val as Record<string, unknown>)" :key="fieldKey">
              <!-- Minimal ROI special editor -->
              <div
                v-if="fieldKey === 'minimal_roi' && isSection(fieldVal)"
                class="col-span-3"
              >
                <label class="text-base text-muted-color mb-1 block">minimal_roi</label>
                <div class="flex gap-2 flex-wrap">
                  <div
                    v-for="(roiVal, roiKey) in (fieldVal as Record<string, number>)"
                    :key="roiKey"
                    class="flex items-center gap-1"
                  >
                    <input
                      type="text"
                      :value="roiKey"
                      class="w-12 px-1 py-1 rounded-sm text-base text-center border dark:border-surface-700 dark:bg-surface-900"
                      @change="updateRoiKey(roiKey as string, $event)"
                    />
                    <span class="text-base text-muted-color">m →</span>
                    <input
                      type="number"
                      :value="roiVal"
                      step="0.001"
                      class="w-20 px-1 py-1 rounded-sm text-base border dark:border-surface-700 dark:bg-surface-900"
                      @change="updateRoiVal(roiKey as string, $event)"
                    />
                  </div>
                </div>
              </div>

              <!-- Array editor -->
              <div
                v-else-if="Array.isArray(fieldVal)"
                class="col-span-3"
              >
                <label class="text-base text-muted-color mb-1 block">{{ fieldKey }}</label>
                <div class="flex gap-2 flex-wrap">
                  <input
                    v-for="(item, idx) in fieldVal"
                    :key="idx"
                    :type="typeof item === 'number' ? 'number' : 'text'"
                    :value="item"
                    :step="typeof item === 'number' ? 'any' : undefined"
                    class="w-32 px-2 py-1 rounded-sm text-base border dark:border-surface-700 dark:bg-surface-900"
                    @change="updateArrayItem(sectionKey as string, fieldKey as string, idx, $event)"
                  />
                </div>
              </div>

              <!-- Boolean -->
              <div v-else-if="typeof fieldVal === 'boolean'" class="flex items-center gap-2">
                <input
                  type="checkbox"
                  :checked="fieldVal"
                  class="accent-emerald-500"
                  @change="updateValue(sectionKey as string, fieldKey as string, $event)"
                />
                <label class="text-base text-muted-color">{{ fieldKey }}</label>
              </div>

              <!-- Number / String -->
              <div v-else-if="typeof fieldVal === 'number' || typeof fieldVal === 'string'" class="flex flex-col gap-1">
                <label class="text-base text-muted-color">{{ fieldKey }}</label>
                <input
                  :type="inputType(fieldVal)"
                  :value="fieldVal"
                  :step="typeof fieldVal === 'number' ? 'any' : undefined"
                  class="px-2 py-1 rounded-sm text-base border dark:border-surface-700 dark:bg-surface-900"
                  @change="updateValue(sectionKey as string, fieldKey as string, $event)"
                />
              </div>
            </template>
          </div>
        </div>
      </template>

      <!-- Bottom save buttons -->
      <div class="flex gap-2 justify-end pb-4">
        <button
          class="px-4 py-2 rounded-md text-base font-bold"
          style="background: #238636; color: #fff; border: none; cursor: pointer"
          :disabled="saving"
          @click="saveConfig"
        >
          Save
        </button>
        <button
          class="px-4 py-2 rounded-md text-base font-bold"
          style="background: #f85149; color: #fff; border: none; cursor: pointer"
          :disabled="saving"
          @click="saveAndRestart"
        >
          Save & Restart Bot
        </button>
      </div>
    </template>
  </div>
</template>
